use std::env;
use std::fs;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <file>", args[0]);
        process::exit(1);
    }
    let content = fs::read_to_string(&args[1]).unwrap_or_else(|e| {
        eprintln!("error reading {}: {}", args[1], e);
        process::exit(1);
    });

    // Parse sections: each section has a name, an optional inherits, and ordered key-value pairs
    struct Section {
        name: String,
        inherits: Option<String>,
        keys: Vec<String>,
        values: std::collections::HashMap<String, String>,
    }

    let mut sections: Vec<Section> = Vec::new();
    let mut current: Option<Section> = None;

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            if let Some(s) = current.take() {
                sections.push(s);
            }
            let name = trimmed[1..trimmed.len() - 1].to_string();
            current = Some(Section {
                name,
                inherits: None,
                keys: Vec::new(),
                values: std::collections::HashMap::new(),
            });
            continue;
        }

        let sec = match current.as_mut() {
            Some(s) => s,
            None => {
                eprintln!("key-value pair outside section: {}", trimmed);
                process::exit(1);
            }
        };

        // Parse key = "value"
        let eq_pos = match trimmed.find('=') {
            Some(p) => p,
            None => {
                eprintln!("malformed line: {}", trimmed);
                process::exit(1);
            }
        };
        let key = trimmed[..eq_pos].trim().to_string();
        let raw_value = trimmed[eq_pos + 1..].trim();

        // Strip quotes if present
        let value = if raw_value.starts_with('"') && raw_value.ends_with('"') && raw_value.len() >= 2 {
            raw_value[1..raw_value.len() - 1].to_string()
        } else {
            raw_value.to_string()
        };

        if key == "inherits" {
            sec.inherits = Some(value);
            continue;
        }

        if sec.values.contains_key(&key) {
            eprintln!("duplicate key '{}' in section [{}]", key, sec.name);
            process::exit(1);
        }

        sec.keys.push(key.clone());
        sec.values.insert(key, value);
    }

    if let Some(s) = current.take() {
        sections.push(s);
    }

    // Build a name -> index map for inheritance lookup
    let name_to_idx: std::collections::HashMap<&str, usize> = sections
        .iter()
        .enumerate()
        .map(|(i, s)| (s.name.as_str(), i))
        .collect();

    // Resolve and print each section
    for section in &sections {
        // Collect resolved fields: start with inherited, then overlay own
        let mut resolved_keys: Vec<String> = Vec::new();
        let mut resolved_values: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();

        if let Some(ref parent_name) = section.inherits {
            if let Some(&idx) = name_to_idx.get(parent_name.as_str()) {
                let parent = &sections[idx];
                for key in &parent.keys {
                    resolved_keys.push(key.clone());
                    resolved_values.insert(key.clone(), parent.values[key].clone());
                }
            } else {
                eprintln!(
                    "section [{}] inherits from unknown section '{}'",
                    section.name, parent_name
                );
                process::exit(1);
            }
        }

        // Overlay own fields
        for key in &section.keys {
            if !resolved_values.contains_key(key) {
                resolved_keys.push(key.clone());
            }
            resolved_values.insert(key.clone(), section.values[key].clone());
        }

        for key in &resolved_keys {
            println!("{}.{}={}", section.name, key, resolved_values[key]);
        }
    }
}

